package main

import (
	"context"
	"log"
	"net/http"
	"time"

	"travel-app-backend/internal/bookings"
	"travel-app-backend/internal/database"
	"travel-app-backend/internal/hotels"
	"travel-app-backend/internal/middleware"
	pkgcfg "travel-app-backend/internal/pkg/config"
	pkgfb "travel-app-backend/internal/pkg/firebase"
	pkgmw "travel-app-backend/internal/pkg/middleware"
	"travel-app-backend/internal/places"
	"travel-app-backend/internal/users"

	// Swagger/OpenAPI docs (generated by swag init).
	_ "travel-app-backend/docs"

	"github.com/gin-gonic/gin"
	"github.com/joho/godotenv"
	swaggerFiles "github.com/swaggo/files"
	ginSwagger "github.com/swaggo/gin-swagger"
)

// @title			Tourapp API
// @version		3.0
// @description	Travel Planning App backend — places, foods, hotels, bookings, users. Discovery routes are public; favorites/bookings/users require `Authorization: Bearer <FIREBASE_ID_TOKEN>` (Firebase ID token obtained by the mobile app via Firebase Auth). Legacy password auth (/users/login, /users/register) is deprecated.
// @BasePath		/api/v1
//
// @securityDefinitions.apikey	BearerAuth
// @in							header
// @name						Authorization
// @description				Firebase ID token: `Bearer <FIREBASE_ID_TOKEN>` (verify via signInWithPassword/getIdToken on the client).
func main() {
	_ = godotenv.Load()

	cfg, err := pkgcfg.Load()
	if err != nil {
		log.Fatalf("config: %v", err)
	}

	ctx := context.Background()

	// Firebase Admin SDK (fail fast on bad/missing service-account creds).
	fb, err := pkgfb.Init(ctx, pkgfb.Credentials{
		ServiceAccountJSON: cfg.FirebaseServiceAccountJSON,
		File:               cfg.FirebaseCredentialsFile,
	})
	if err != nil {
		log.Fatalf("firebase: %v", err)
	}
	log.Println("[firebase] Admin SDK initialized")

	pool, err := database.NewPool(ctx)
	if err != nil {
		log.Fatalf("database: %v", err)
	}
	defer pool.Close()

	if err := database.Migrate(ctx, pool); err != nil {
		log.Fatalf("migrate: %v", err)
	}
	if err := database.Seed(ctx, pool); err != nil {
		log.Fatalf("seed: %v", err)
	}

	if cfg.GinMode != "" {
		gin.SetMode(cfg.GinMode)
	}

	r := gin.New()
	r.Use(middleware.Recovery(), middleware.Logger(), middleware.CORS(cfg.CORSAllowedOrigins))

	api := r.Group("/api/v1")

	// Public discovery routes — preset-data policy: every read is served
	// from Neon; nothing is fetched at runtime (seed via cmd/bootstrap).
	placesRepo := places.NewPostgresRepository(pool)
	placesService := places.NewService(placesRepo)
	placesHandler := places.NewHandler(placesService)
	placesHandler.RegisterPublic(api)

	hotelsRepo := hotels.NewPostgresRepository(pool)
	hotelsService := hotels.NewService(hotelsRepo)
	hotelsHandler := hotels.NewHandler(hotelsService)
	hotelsHandler.RegisterPublic(api)

	usersRepo := users.NewPostgresRepository(pool)
	usersService := users.NewService(usersRepo)
	usersHandler := users.NewHandler(usersService)
	usersHandler.RegisterPublic(api)

	// Authenticated routes (Firebase ID token required).
	// The middleware verifies the token and upserts the Neon user first,
	// so usersRepo is a dependency of the group itself.
	authorized := api.Group("")
	authorized.Use(pkgmw.FirebaseAuthMiddleware(fb, usersRepo))

	placesHandler.RegisterProtected(authorized)

	bookingsRepo := bookings.NewPostgresRepository(pool)
	bookingsHandler := bookings.NewHandler(bookings.NewService(bookingsRepo))
	bookingsHandler.RegisterProtected(authorized)

	usersHandler.RegisterProtected(authorized)

	r.GET("/health", func(c *gin.Context) {
		pingCtx, cancel := context.WithTimeout(ctx, 3*time.Second)
		defer cancel()
		status := http.StatusOK
		body := gin.H{"success": true, "status": "ok"}
		if err := pool.Ping(pingCtx); err != nil {
			status = http.StatusServiceUnavailable
			body = gin.H{"success": false, "status": "db unavailable"}
		}
		c.JSON(status, body)
	})

	// OpenAPI UI for mobile clients: /swagger/index.html
	r.GET("/swagger/*any", ginSwagger.WrapHandler(swaggerFiles.Handler))

	if err := r.Run(":" + cfg.Port); err != nil {
		log.Fatalf("server: %v", err)
	}
}
